const body =
  $json.body ??
  $json;

const base64 =
  String(
    body.audioBase64 ||
    ""
  );

const mimeType =
  String(
    body.mimeType ||
    "audio/webm"
  );

if (!base64) {
  throw new Error(
    "audioBase64 is missing"
  );
}

const cleanBase64 =
  base64.includes(",")
    ? base64.split(",")[1]
    : base64;

const audioBuffer =
  Buffer.from(
    cleanBase64,
    "base64"
  );

if (
  audioBuffer.length <
  500
) {
  throw new Error(
    `Audio recording is too small: ${audioBuffer.length} bytes`
  );
}

let extension =
  "webm";

if (
  mimeType.includes(
    "ogg"
  )
) {
  extension = "ogg";
} else if (
  mimeType.includes(
    "mp4"
  )
) {
  extension = "mp4";
} else if (
  mimeType.includes(
    "mpeg"
  )
) {
  extension = "mp3";
}

const binary =
  await this.helpers.prepareBinaryData(
    audioBuffer,
    `voice_input.${extension}`,
    mimeType
  );

return [
  {
    json: {
      sessionId:
        body.sessionId ||
        "",

      email:
        body.email ||
        "",

      action:
        body.action ||
        "",

      selectedDoctor:
        body.selectedDoctor ||
        null,

      selectedDate:
        body.selectedDate ||
        "",

      displayDate:
        body.displayDate ||
        "",

      dayName:
        body.dayName ||
        "",

      selectedTime:
        body.selectedTime ||
        "",

      appointmentId:
        body.appointmentId ||
        "",

      cancellationReason:
        body.cancellationReason ||
        "",

      newAppointmentDate:
        body.newAppointmentDate ||
        "",

      newAppointmentTime:
        body.newAppointmentTime ||
        "",

      requestVoiceReply:
        true,

      voiceMode:
        true,

      mimeType,

      audioBytes:
        audioBuffer.length,
    },

    binary: {
      audioFile:
        binary,
    },
  },
];

const item = $json;

const sessionId =
  item.sessionId || "default";

const voiceMode =
  item.voiceMode === true ||
  item.requestVoiceReply === true;

const store =
  $getWorkflowStaticData(
    "global"
  );

if (!store.bookingStates) {
  store.bookingStates = {};
}

if (!store.appointmentActionStates) {
  store.appointmentActionStates = {};
}

let state =
  store.bookingStates[
    sessionId
  ] || {
    stage: "idle",
  };

let operationState =
  store.appointmentActionStates[
    sessionId
  ] || {
    type: "",
    stage: "idle",
    appointmentId: "",
    newAppointmentDate: "",
    newAppointmentTime: "",
    cancellationReason: "",
  };

/*
 * ==================================================
 * INPUT NORMALIZATION
 * ==================================================
 *
 * Text:
 *   item.message
 *
 * Voice:
 *   STT output should already be placed into
 *   normalizedMessage/message/transcript.
 *
 * Both then use the same NLP/state logic.
 * ==================================================
 */

const originalMessage =
  String(
    item.normalizedMessage ||
      item.message ||
      item.transcript ||
      ""
  ).trim();

const msg =
  originalMessage
    .toLowerCase()
    .replace(/[,?.!]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

/*
 * ==================================================
 * HELPERS
 * ==================================================
 */

function parseDoctor(raw) {
  if (!raw) {
    return null;
  }

  if (
    typeof raw ===
    "object"
  ) {
    return raw;
  }

  try {
    return JSON.parse(
      raw
    );
  } catch {
    return null;
  }
}

function isoLocal(date) {
  const year =
    date.getFullYear();

  const month =
    String(
      date.getMonth() + 1
    ).padStart(
      2,
      "0"
    );

  const day =
    String(
      date.getDate()
    ).padStart(
      2,
      "0"
    );

  return `${year}-${month}-${day}`;
}

function dayName(
  dateString
) {
  if (!dateString) {
    return "";
  }

  const date =
    new Date(
      `${dateString}T12:00:00`
    );

  return [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday",
  ][date.getDay()];
}

/*
 * ==================================================
 * NATURAL DATE PARSER
 * ==================================================
 *
 * Supports BOTH text and voice:
 *
 * today
 * tomorrow
 * 2026-10-05
 * October 5
 * October fifth
 * October 5th
 * fifth October
 * fifth of October
 * 5 October
 * 5th of October
 *
 * Also supports:
 * twenty first of October
 * October twenty first
 * etc.
 * ==================================================
 */

function extractDate(
  text
) {
  const normalized =
    String(
      text || ""
    )
      .toLowerCase()
      .replace(
        /,/g,
        " "
      )
      .replace(
        /\s+/g,
        " "
      )
      .trim();

  const now =
    new Date();

  now.setHours(
    0,
    0,
    0,
    0
  );

  /*
   * TODAY
   */
  if (
    /\btoday\b/.test(
      normalized
    )
  ) {
    return isoLocal(
      now
    );
  }

  /*
   * TOMORROW
   */
  if (
    /\btomorrow\b/.test(
      normalized
    )
  ) {
    const tomorrow =
      new Date(
        now
      );

    tomorrow.setDate(
      tomorrow.getDate() +
        1
    );

    return isoLocal(
      tomorrow
    );
  }

  /*
   * ISO format:
   * 2026-10-05
   */
  const iso =
    normalized.match(
      /\b(20\d{2}-\d{2}-\d{2})\b/
    );

  if (iso) {
    return iso[1];
  }

  const months = {
    january: 0,
    february: 1,
    march: 2,
    april: 3,
    may: 4,
    june: 5,
    july: 6,
    august: 7,
    september: 8,
    october: 9,
    november: 10,
    december: 11,
  };

  const ordinalWords = {
    first: 1,
    second: 2,
    third: 3,
    fourth: 4,
    fifth: 5,
    sixth: 6,
    seventh: 7,
    eighth: 8,
    ninth: 9,
    tenth: 10,
    eleventh: 11,
    twelfth: 12,
    thirteenth: 13,
    fourteenth: 14,
    fifteenth: 15,
    sixteenth: 16,
    seventeenth: 17,
    eighteenth: 18,
    nineteenth: 19,
    twentieth: 20,

    "twenty first": 21,
    "twenty-first": 21,

    "twenty second": 22,
    "twenty-second": 22,

    "twenty third": 23,
    "twenty-third": 23,

    "twenty fourth": 24,
    "twenty-fourth": 24,

    "twenty fifth": 25,
    "twenty-fifth": 25,

    "twenty sixth": 26,
    "twenty-sixth": 26,

    "twenty seventh": 27,
    "twenty-seventh": 27,

    "twenty eighth": 28,
    "twenty-eighth": 28,

    "twenty ninth": 29,
    "twenty-ninth": 29,

    thirtieth: 30,

    "thirty first": 31,
    "thirty-first": 31,
  };

  function resolveDay(
    value
  ) {
    if (!value) {
      return 0;
    }

    const clean =
      String(value)
        .toLowerCase()
        .trim();

    /*
     * 5
     * 5th
     * 21st
     */
    const numeric =
      clean.match(
        /^(\d{1,2})(?:st|nd|rd|th)?$/
      );

    if (numeric) {
      return Number(
        numeric[1]
      );
    }

    return (
      ordinalWords[
        clean
      ] || 0
    );
  }

  const monthPattern =
    Object.keys(
      months
    ).join("|");

  const ordinalPattern =
    Object.keys(
      ordinalWords
    )
      .sort(
        (a, b) =>
          b.length -
          a.length
      )
      .map(
        (word) =>
          word.replace(
            /[-\s]+/g,
            "[-\\s]+"
          )
      )
      .join("|");

  /*
   * fifth of October
   * fifth October
   * 5th of October
   * 5 October
   */
  const dayMonth =
    new RegExp(
      `(?:the\\s+)?(${ordinalPattern}|\\d{1,2}(?:st|nd|rd|th)?)\\s+(?:of\\s+)?(${monthPattern})(?:\\s+(20\\d{2}))?`,
      "i"
    );

  /*
   * October fifth
   * October 5th
   * October 5
   */
  const monthDay =
    new RegExp(
      `(${monthPattern})\\s+(?:the\\s+)?(${ordinalPattern}|\\d{1,2}(?:st|nd|rd|th)?)(?:\\s+(20\\d{2}))?`,
      "i"
    );

  let match =
    normalized.match(
      dayMonth
    );

  let day =
    0;

  let month =
    -1;

  let year =
    now.getFullYear();

  let explicitYear =
    false;

  if (match) {
    day =
      resolveDay(
        match[1]
      );

    month =
      months[
        match[2]
          .toLowerCase()
      ];

    if (
      match[3]
    ) {
      year =
        Number(
          match[3]
        );

      explicitYear =
        true;
    }
  } else {
    match =
      normalized.match(
        monthDay
      );

    if (match) {
      month =
        months[
          match[1]
            .toLowerCase()
        ];

      day =
        resolveDay(
          match[2]
        );

      if (
        match[3]
      ) {
        year =
          Number(
            match[3]
          );

        explicitYear =
          true;
      }
    }
  }

  if (
    !day ||
    month < 0
  ) {
    return "";
  }

  let candidate =
    new Date(
      year,
      month,
      day
    );

  candidate.setHours(
    0,
    0,
    0,
    0
  );

  /*
   * Reject impossible dates:
   *
   * February 31
   * April 31
   * etc.
   */
  if (
    candidate.getDate() !==
      day ||
    candidate.getMonth() !==
      month
  ) {
    return "";
  }

  /*
   * If no year was given and the date
   * already passed this year, use next year.
   */
  if (
    !explicitYear &&
    candidate <
      now
  ) {
    candidate =
      new Date(
        year + 1,
        month,
        day
      );
  }

  return isoLocal(
    candidate
  );
}

/*
 * ==================================================
 * ORDINAL PARSER
 * ==================================================
 *
 * Context decides what the ordinal means.
 *
 * awaiting_doctor:
 *   first one = doctor 1
 *
 * awaiting_time:
 *   first one = time slot 1
 *
 * awaiting_date:
 *   date parser runs instead, so
 *   "fifth of October" is NOT doctor 5.
 * ==================================================
 */

function getOrdinalIndex(
  text
) {
  const normalized =
    String(
      text || ""
    )
      .toLowerCase()
      .replace(
        /\s+/g,
        " "
      )
      .trim();

  const patterns = [
    {
      pattern:
        /\b(first one|first|1st|number one|doctor one|dr one|slot one|time one)\b/,
      index: 0,
    },

    {
      pattern:
        /\b(second one|second|2nd|number two|doctor two|dr two|slot two|time two)\b/,
      index: 1,
    },

    {
      pattern:
        /\b(third one|third|3rd|number three|doctor three|dr three|slot three|time three)\b/,
      index: 2,
    },

    {
      pattern:
        /\b(fourth one|fourth|4th|number four|doctor four|dr four|slot four|time four)\b/,
      index: 3,
    },

    {
      pattern:
        /\b(fifth one|fifth|5th|number five|doctor five|dr five|slot five|time five)\b/,
      index: 4,
    },

    {
      pattern:
        /\b(sixth one|sixth|6th|number six|doctor six|dr six|slot six|time six)\b/,
      index: 5,
    },
  ];

  for (
    const entry
    of patterns
  ) {
    if (
      entry.pattern.test(
        normalized
      )
    ) {
      return entry.index;
    }
  }

  return -1;
}

/*
 * ==================================================
 * DOCTOR MATCHING
 * ==================================================
 */

function matchDoctor(
  text,
  doctors
) {
  if (
    !Array.isArray(
      doctors
    ) ||
    doctors.length === 0
  ) {
    return null;
  }

  /*
   * Ordinal selection:
   *
   * first doctor
   * first one
   * go with the first one
   */
  const ordinal =
    getOrdinalIndex(
      text
    );

  if (
    ordinal >= 0 &&
    doctors[ordinal]
  ) {
    return doctors[
      ordinal
    ];
  }

  /*
   * Match doctor names:
   *
   * Chamodi
   * Dr Chamodi
   * Chamodi Bandara
   */
  let bestDoctor =
    null;

  let bestScore =
    0;

  for (
    const doctor
    of doctors
  ) {
    const doctorName =
      String(
        doctor.doctorName ||
          doctor.name ||
          ""
      )
        .toLowerCase()
        .replace(
          /\bdoctor\b/g,
          ""
        )
        .replace(
          /\bdr\.?\b/g,
          ""
        )
        .trim();

    const nameParts =
      doctorName
        .split(
          /\s+/
        )
        .filter(
          (part) =>
            part.length >
            2
        );

    const score =
      nameParts.filter(
        (part) =>
          text.includes(
            part
          )
      ).length;

    if (
      score >
      bestScore
    ) {
      bestScore =
        score;

      bestDoctor =
        doctor;
    }
  }

  return bestScore > 0
    ? bestDoctor
    : null;
}

/*
 * ==================================================
 * TIME MATCHING
 * ==================================================
 *
 * Supports:
 *
 * first
 * first one
 * first time
 * first slot
 *
 * second
 * second one
 * second time slot
 *
 * 5 pm
 * 5:00 pm
 *
 * exact slot text
 * ==================================================
 */

function extractTime(
  text,
  slots
) {
  if (
    !Array.isArray(
      slots
    ) ||
    slots.length === 0
  ) {
    return "";
  }

  const normalized =
    String(
      text || ""
    )
      .toLowerCase()
      .replace(
        /\s+/g,
        " "
      )
      .trim();

  const ordinal =
    getOrdinalIndex(
      normalized
    );

  if (
    ordinal >= 0 &&
    slots[ordinal]
  ) {
    const candidate =
      slots[ordinal];

    if (
      typeof candidate === "object" &&
      candidate?.booked === true
    ) {
      return "";
    }

    return String(
      candidate?.label ||
      candidate
    );
  }

  for (
    const slot
    of slots
  ) {
    if (
      typeof slot === "object" &&
      slot?.booked === true
    ) {
      continue;
    }

    const label =
      String(
        slot?.label ||
          slot
      );

    const lowerLabel =
      label
        .toLowerCase();

    const startingTime =
      lowerLabel
        .split("-")[0]
        .trim();

    if (
      normalized.includes(
        lowerLabel
      ) ||
      normalized.includes(
        startingTime
      )
    ) {
      return label;
    }
  }

  const spokenTime =
    normalized.match(
      /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i
    );

  if (
    spokenTime
  ) {
    const hour =
      spokenTime[1];

    const minutes =
      spokenTime[2] ||
      "00";

    const meridiem =
      spokenTime[3]
        .toUpperCase();

    const requested =
      `${hour}:${minutes} ${meridiem}`;

    for (
      const slot
      of slots
    ) {
      if (
        typeof slot === "object" &&
        slot?.booked === true
      ) {
        continue;
      }

      const label =
        String(
          slot?.label ||
            slot
        );

      if (
        label
          .toLowerCase()
          .includes(
            requested
              .toLowerCase()
          )
      ) {
        return label;
      }
    }
  }

  return "";
}


/*
 * ==================================================
 * CANCEL / RESCHEDULE HELPERS
 * ==================================================
 */

function extractAppointmentId(
  text
) {
  const normalized =
    String(text || "")
      .toLowerCase()
      .replace(/[,?.!]/g, " ")
      .replace(/\s+/g, " ")
      .trim();

  const explicit =
    normalized.match(
      /\b(?:appointment|appointment number|appointment id|reference|reference number|booking|booking number)\s*(?:number|id|no\.?)?\s*#?\s*(\d+)\b/i
    );

  if (explicit) {
    return explicit[1];
  }

  if (
    operationState.stage ===
      "cancel_awaiting_id" ||
    operationState.stage ===
      "reschedule_awaiting_id"
  ) {
    const standalone =
      normalized.match(
        /^\s*#?\s*(\d+)\s*$/
      );

    if (standalone) {
      return standalone[1];
    }
  }

  return "";
}

function extractFlexibleTime(
  text
) {
  let normalized =
    String(text || "")
      .toLowerCase()
      .replace(/[,?.!]/g, " ")
      .replace(/\s+/g, " ")
      .trim();

  const wordHours = {
    one: "1",
    two: "2",
    three: "3",
    four: "4",
    five: "5",
    six: "6",
    seven: "7",
    eight: "8",
    nine: "9",
    ten: "10",
    eleven: "11",
    twelve: "12",
  };

  normalized =
    normalized.replace(
      /\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s*(am|pm)\b/g,
      (_, word, meridiem) =>
        `${wordHours[word]} ${meridiem}`
    );

  const range =
    normalized.match(
      /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\s*(?:-|to)\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i
    );

  if (range) {
    const startMinutes =
      range[2] || "00";

    const endMinutes =
      range[5] || "00";

    return `${Number(range[1])}:${startMinutes} ${range[3].toUpperCase()} - ${Number(range[4])}:${endMinutes} ${range[6].toUpperCase()}`;
  }

  const single =
    normalized.match(
      /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i
    );

  if (single) {
    const minutes =
      single[2] || "00";

    return `${Number(single[1])}:${minutes} ${single[3].toUpperCase()}`;
  }

  return "";
}

function isYes(
  text
) {
  return /^(yes|yeah|yep|confirm|confirmed|please do|do it|go ahead|sure|okay|ok)$/i.test(
    String(text || "").trim()
  );
}

function isNo(
  text
) {
  return /^(no|nope|cancel that|stop|never mind|nevermind|do not|don't)$/i.test(
    String(text || "").trim()
  );
}

function saveOperationState() {
  store.appointmentActionStates[
    sessionId
  ] = operationState;
}

function clearOperationState() {
  delete store
    .appointmentActionStates[
      sessionId
    ];

  operationState = {
    type: "",
    stage: "idle",
    appointmentId: "",
    newAppointmentDate: "",
    newAppointmentTime: "",
    cancellationReason: "",
  };
}

/*
 * ==================================================
 * INTENT / ACTION FLAGS
 * ==================================================
 */

const action =
  String(
    item.action ||
      ""
  )
    .toLowerCase()
    .trim();

const selectedDoctor =
  parseDoctor(
    item.selectedDoctor
  );

const asksForDoctorList =
  /\b(available doctors|available doctor|who are the doctors|list doctors|show doctors|doctors available)\b/.test(
    msg
  );

/*
 * A bare mention of the word "appointment" is NOT a booking request.
 *
 * This prevents informational questions such as:
 *   "How early should I arrive for my appointment?"
 * from incorrectly starting a new booking flow.
 */
const startsBooking =
  (
    /\b(book|booking|schedule|reserve)\b/.test(
      msg
    ) &&
    /\b(appointment|consultation|doctor|dr)\b/.test(
      msg
    )
  ) ||
  /\bnew appointment\b/.test(
    msg
  );

/*
 * A new general booking request.
 *
 * Examples:
 *
 * Can I book an appointment?
 * I want to book an appointment
 * Book an appointment
 * Schedule an appointment
 */
const freshBookingRequest =
  startsBooking &&
  /\b(can i book|i want to book|i would like to book|book an appointment|make an appointment|schedule an appointment|new appointment)\b/.test(
    msg
  ) &&
  !selectedDoctor;

/*
 * Availability language.
 */
const asksAvailability =
  /\b(available dates|available date|available days|what days|which days|what dates|which dates|available times|available time|what times|which times|when is|when are|availability|show availability|tell me.*available)\b/.test(
    msg
  );

/*
 * Verified administrative / medical-center information.
 *
 * These questions should go to RAG even while a booking,
 * cancellation, or reschedule conversation is active.
 */
const asksFAQ =
  /\b(hour|hours|open|opening|close|closed|closing|location|address|contact|phone|email|fee|fees|cost|price|insurance|walk-in|walk in|service|services|laboratory|lab|blood test|blood tests|fast|fasting|sample|samples|report|reports|pharmacy|parking|wheelchair|accessible|accessibility|landmark|holiday|holidays|sunday|privacy|arrival|arrive|check in|check-in|bring|identification)\b/.test(
    msg
  );

/*
 * Appointment-policy questions are informational, not actions.
 *
 * Examples:
 *   "How early should I arrive for my appointment?"
 *   "What should I bring to my appointment?"
 *   "What is your cancellation policy?"
 *   "Can I reschedule an appointment?"
 *   "How do appointments work?"
 */
const asksAppointmentPolicyFAQ =
  /\b(how early|when should i arrive|what should i bring|what do i bring|do i need (?:an )?(?:id|identification)|appointment policy|appointment policies|cancellation policy|cancelation policy|rescheduling policy|reschedule policy|appointment rules|how do appointments work|how does an appointment work|before (?:my|the|an) appointment|can i reschedule (?:an|the) appointment|how can i reschedule (?:an|the) appointment|can i cancel (?:an|the) appointment|how can i cancel (?:an|the) appointment)\b/.test(
    msg
  );

const asksInformationalFAQ =
  asksFAQ ||
  asksAppointmentPolicyFAQ;

const asksSymptoms =
  /\b(chest pain|chest tightness|shortness of breath|difficulty breathing|breath|bleeding|stroke|fever|headache|migraine|dizzy|dizziness|pain|symptom|cough|sore throat|cold|flu|vomit|vomiting|nausea|diarrhea|rash|fatigue|weakness|numb|numbness|seizure|palpitation|palpitations|heart racing|stomach pain|abdominal pain|back pain|child|baby|pediatric|paediatric|not feeling well|feel unwell|feeling unwell)\b/.test(
    msg
  );

const startsCancellation =
  action === "cancel_appointment" ||
  /\b(cancel|cancelled|cancellation)\b/.test(
    msg
  );

const startsReschedule =
  action === "reschedule_appointment" ||
  /\b(reschedule|rescheduled|move appointment|change appointment|change my appointment|move my appointment)\b/.test(
    msg
  );

const providedAppointmentId =
  String(
    item.appointmentId ||
    extractAppointmentId(msg) ||
    ""
  ).trim();

const providedNewDate =
  String(
    item.newAppointmentDate ||
    ""
  ).trim() ||
  extractDate(msg);

const providedNewTime =
  String(
    item.newAppointmentTime ||
    ""
  ).trim() ||
  extractFlexibleTime(msg);

let route =
  "general";


/*
 * ==================================================
 * CANCEL / RESCHEDULE STATE MACHINE
 * ==================================================
 *
 * This is intentionally separate from bookingStates
 * so the proven booking flow is not overwritten.
 */

/*
 * ==================================================
 * FRESH CANCEL / RESCHEDULE REQUESTS
 * ==================================================
 *
 * An explicit command containing an appointment ID
 * always starts a fresh operation, even if an older
 * operation state was left behind by a previous
 * interrupted workflow execution.
 */

/*
 * ==================================================
 * GLOBAL INFORMATIONAL INTERRUPT
 * ==================================================
 *
 * FAQ / policy questions are allowed to interrupt an
 * in-progress booking, cancellation, or reschedule flow.
 *
 * IMPORTANT:
 * We route the current turn to RAG without clearing either
 * bookingStates or appointmentActionStates. The user can ask
 * an informational question and then continue the previous
 * appointment flow on the next turn.
 *
 * Structured UI actions must never be intercepted here.
 */
if (
  !action &&
  asksInformationalFAQ
) {
  route =
    "faq";
}

/*
 * Fresh cancellation request.
 */
else if (
  startsCancellation &&
  (
    operationState.stage === "idle" ||
    providedAppointmentId
  )
) {
  /*
   * Cancel any stale booking conversation state.
   * Appointment management takes priority.
   */
  state = {
    ...state,
    stage: "idle",
    selectedDoctor: null,
    selectedDate: "",
    displayDate: "",
    dayName: "",
    selectedTime: "",
    availableSlots: [],
    availabilitySummaryRequested: false,
  };

  store.bookingStates[
    sessionId
  ] = state;

  operationState = {
    type: "cancel",

    stage:
      providedAppointmentId
        ? "lookup"
        : "cancel_awaiting_id",

    appointmentId:
      providedAppointmentId,

    newAppointmentDate: "",

    newAppointmentTime: "",

    cancellationReason:
      String(
        item.cancellationReason ||
        ""
      ).trim(),
  };

  saveOperationState();

  route =
    providedAppointmentId
      ? "appointment_lookup"
      : "operation_prompt";
}

/*
 * Fresh reschedule request.
 */
else if (
  startsReschedule &&
  (
    operationState.stage === "idle" ||
    providedAppointmentId
  )
) {
  /*
   * Reset stale normal-booking state.
   * Rescheduling is a different operation.
   */
  state = {
    ...state,
    stage: "idle",
    selectedDoctor: null,
    selectedDate: "",
    displayDate: "",
    dayName: "",
    selectedTime: "",
    availableSlots: [],
    availabilitySummaryRequested: false,
  };

  store.bookingStates[
    sessionId
  ] = state;

  operationState = {
    type: "reschedule",

    stage:
      providedAppointmentId
        ? "lookup"
        : "reschedule_awaiting_id",

    appointmentId:
      providedAppointmentId,

    newAppointmentDate:
      providedNewDate,

    newAppointmentTime:
      providedNewTime,

    cancellationReason: "",
  };

  saveOperationState();

  route =
    providedAppointmentId
      ? "appointment_lookup"
      : "operation_prompt";
}

/*
 * Waiting for cancellation appointment number.
 */
else if (
  operationState.stage ===
    "cancel_awaiting_id"
) {
  const id =
    providedAppointmentId ||
    extractAppointmentId(msg);

  if (id) {
    operationState.appointmentId =
      id;

    operationState.stage =
      "lookup";

    saveOperationState();

    route =
      "appointment_lookup";
  } else {
    route =
      "operation_prompt";
  }
}

/*
 * Waiting for reschedule appointment number.
 */
else if (
  operationState.stage ===
    "reschedule_awaiting_id"
) {
  const id =
    providedAppointmentId ||
    extractAppointmentId(msg);

  if (id) {
    operationState.appointmentId =
      id;

    if (providedNewDate) {
      operationState.newAppointmentDate =
        providedNewDate;
    }

    if (providedNewTime) {
      operationState.newAppointmentTime =
        providedNewTime;
    }

    operationState.stage =
      "lookup";

    saveOperationState();

    route =
      "appointment_lookup";
  } else {
    route =
      "operation_prompt";
  }
}

/*
 * Cancellation confirmation.
 */
else if (
  operationState.stage ===
    "cancel_awaiting_confirmation"
) {
  if (
    isYes(msg)
  ) {
    operationState.stage =
      "cancel_executing";

    saveOperationState();

    route =
      "appointment_cancel";
  } else if (
    isNo(msg)
  ) {
    clearOperationState();

    route =
      "operation_prompt";

    item.operationPrompt =
      "Okay, I will not cancel that appointment.";
  } else {
    route =
      "operation_prompt";
  }
}

/*
 * Waiting for new reschedule date.
 */
else if (
  operationState.stage ===
    "reschedule_awaiting_date"
) {
  const date =
    providedNewDate ||
    extractDate(msg);

  if (date) {
    operationState.newAppointmentDate =
      date;

    const time =
      providedNewTime ||
      extractFlexibleTime(msg);

    if (time) {
      operationState.newAppointmentTime =
        time;

      operationState.stage =
        "reschedule_executing";

      saveOperationState();

      route =
        "appointment_reschedule";
    } else {
      /*
       * Date was selected but no time was supplied.
       * Query the doctor's configured schedule plus
       * current DB bookings before showing time buttons.
       */
      operationState.newAppointmentTime =
        "";

      operationState.stage =
        "reschedule_loading_slots";

      saveOperationState();

      route =
        "reschedule_slots";
    }
  } else {
    route =
      "operation_prompt";
  }
}

/*
 * Waiting for new reschedule time.
 */
else if (
  operationState.stage ===
    "reschedule_awaiting_time"
) {
  const time =
    providedNewTime ||
    extractFlexibleTime(msg);

  if (time) {
    operationState.newAppointmentTime =
      time;

    operationState.stage =
      "reschedule_executing";

    saveOperationState();

    route =
      "appointment_reschedule";
  } else {
    route =
      "operation_prompt";
  }
}

/*
 * ==================================================
 * SYMPTOM -> DOCTOR BOOKING HANDOFF
 * ==================================================
 *
 * The symptom recommendation flow stores one real
 * doctor in bookingStates and waits for the patient
 * to accept or decline the suggested booking.
 *
 * Text and voice both arrive here after normalization.
 */
else if (
  state.stage ===
    "awaiting_symptom_booking_confirmation"
) {
  const acceptsRecommendation =
    isYes(msg) ||
    /\b(yes please|book it|book with (?:this|that|the) doctor|book (?:this|that) doctor|i(?:'d| would) like to book|make the appointment|schedule it|go ahead and book)\b/i.test(
      originalMessage
    );

  const declinesRecommendation =
    isNo(msg) ||
    /\b(not now|maybe later|no thanks|no thank you|do not book|don't book)\b/i.test(
      originalMessage
    );

  if (
    acceptsRecommendation &&
    state.selectedDoctor
  ) {
    state.stage =
      "awaiting_date";

    state.selectedDate =
      "";

    state.displayDate =
      "";

    state.dayName =
      "";

    state.selectedTime =
      "";

    state.availableSlots =
      [];

    state.availabilitySummaryRequested =
      false;

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_calendar";
  } else if (
    declinesRecommendation
  ) {
    state = {
      ...state,

      stage:
        "idle",

      selectedDoctor:
        null,

      selectedDate:
        "",

      displayDate:
        "",

      dayName:
        "",

      selectedTime:
        "",

      availableSlots:
        [],

      symptomContext:
        null,
    };

    store.bookingStates[
      sessionId
    ] = state;

    item.symptomFollowupPrompt =
      "Okay, I will not start an appointment booking. If your symptoms worsen or you develop urgent warning signs, seek prompt in-person medical care. You can ask me about another doctor or start a booking whenever you are ready.";

    route =
      "symptom";
  } else {
    store.bookingStates[
      sessionId
    ] = state;

    const doctorName =
      state.selectedDoctor?.doctorName ||
      state.selectedDoctor?.name ||
      "the recommended doctor";

    item.symptomFollowupPrompt =
      `Would you like to book an appointment with ${doctorName}? Please say yes to continue to date selection, or no to continue without booking.`;

    route =
      "symptom";
  }
}

/*
 * ==================================================
 * 1. STRUCTURED UI: DOCTOR SELECTED
 * ==================================================
 *
 * Existing Doctor Card button.
 */

else if (
  action ===
    "select_doctor" ||
  action ===
    "has_doctor"
) {
  if (
    selectedDoctor
  ) {
    state.selectedDoctor =
      selectedDoctor;

    state.stage =
      "awaiting_date";

    state.selectedDate =
      "";

    state.displayDate =
      "";

    state.dayName =
      "";

    state.selectedTime =
      "";

    state.availableSlots =
      [];

    state.availabilitySummaryRequested =
      false;

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_calendar";
  } else {
    route =
      "booking_doctors";
  }
}

/*
 * ==================================================
 * 2. STRUCTURED UI: DATE SELECTED
 * ==================================================
 *
 * Calendar click.
 */

else if (
  action ===
  "select_date"
) {
  const date =
    String(
      item.selectedDate ||
        ""
    );

  state.selectedDate =
    date;

  state.displayDate =
    item.displayDate ||
    date;

  state.dayName =
    item.dayName ||
    (
      date
        ? dayName(
            date
          )
        : ""
    );

  state.selectedTime =
    "";

  state.availableSlots =
    [];

  state.availabilitySummaryRequested =
    false;

  state.stage =
    "awaiting_time";

  store.bookingStates[
    sessionId
  ] = state;

  route =
    "booking_slots";
}

/*
 * ==================================================
 * 3. STRUCTURED UI: TIME CONFIRMATION
 * ==================================================
 *
 * Time selection from the UI appointment
 * confirmation flow.
 */

else if (
  action ===
  "confirm_booking"
) {
  state.selectedTime =
    String(
      item.selectedTime ||
        ""
    );

  state.stage =
    "confirming";

  store.bookingStates[
    sessionId
  ] = state;

  route =
    "booking_confirm";
}

/*
 * ==================================================
 * 4. FRESH BOOKING
 * ==================================================
 *
 * Supports:
 *
 * "I want to book an appointment"
 *      -> show doctor list
 *
 * "I want to book an appointment with Dr. Chamodi Bandara"
 *      -> select Chamodi immediately if already known
 *      -> go directly to date selection
 *
 * This preserves the existing structured UI flow.
 * ==================================================
 */

else if (
  freshBookingRequest
) {
  const knownDoctors =
    Array.isArray(
      state.currentDoctors
    )
      ? state.currentDoctors
      : [];

  /*
   * Try to identify a doctor mentioned in
   * the user's natural-language booking request.
   */
  const doctorFromMessage =
    matchDoctor(
      msg,
      knownDoctors
    );

  if (
    doctorFromMessage
  ) {
    state = {
      ...state,

      stage:
        "awaiting_date",

      selectedDoctor:
        doctorFromMessage,

      selectedDate:
        "",

      displayDate:
        "",

      dayName:
        "",

      selectedTime:
        "",

      availableSlots:
        [],

      availabilitySummaryRequested:
        false,
    };

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_calendar";
  } else {
    /*
     * No doctor could be identified from the
     * message, so use the existing doctor picker.
     */
    state = {
      stage:
        "idle",

      currentDoctors:
        knownDoctors,

      selectedDoctor:
        null,

      selectedDate:
        "",

      displayDate:
        "",

      dayName:
        "",

      selectedTime:
        "",

      availableSlots:
        [],

      availabilitySummaryRequested:
        false,
    };

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_doctors";
  }
}
/*
 * ==================================================
 * 5. DOCTOR LIST REQUEST
 * ==================================================
 */

else if (
  asksForDoctorList
) {
  state = {
    ...state,

    stage:
      "idle",

    selectedDoctor:
      null,

    selectedDate:
      "",

    displayDate:
      "",

    dayName:
      "",

    selectedTime:
      "",

    availableSlots:
      [],

    availabilitySummaryRequested:
      false,
  };

  store.bookingStates[
    sessionId
  ] = state;

  route =
    "doctors";
}

/*
 * ==================================================
 * 6. WAITING FOR DOCTOR
 * ==================================================
 *
 * CRITICAL:
 *
 * Ordinals are interpreted as doctors ONLY
 * while stage === awaiting_doctor.
 *
 * Therefore:
 *
 * "Go with the first doctor"
 *          ↓
 * doctor 1
 *
 * But after doctor selection:
 *
 * "Fifth of October"
 *
 * will NOT be interpreted as doctor 5.
 * ==================================================
 */

else if (
  state.stage ===
    "awaiting_doctor"
) {
  const doctor =
    matchDoctor(
      msg,
      state.currentDoctors
    );

  if (
    doctor
  ) {
    state.selectedDoctor =
      doctor;

    state.selectedDate =
      "";

    state.displayDate =
      "";

    state.dayName =
      "";

    state.selectedTime =
      "";

    state.availableSlots =
      [];

    state.availabilitySummaryRequested =
      false;

    state.stage =
      "awaiting_date";

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_calendar";
  } else {
    route =
      "booking_doctors";
  }
}

/*
 * ==================================================
 * 7. GENERIC BOOKING START
 * ==================================================
 */

else if (
  startsBooking &&
  !startsCancellation &&
  !startsReschedule &&
  operationState.stage === "idle" &&
  state.stage === "idle"
) {
  route =
    "booking_doctors";
}

/*
 * ==================================================
 * 8. WAITING FOR DATE
 * ==================================================
 *
 * Works for BOTH text and voice:
 *
 * Fifth of October
 * October fifth
 * 5th October
 * October 5
 * today
 * tomorrow
 *
 * Clicking the calendar still works through
 * action === select_date.
 * ==================================================
 */

else if (
  state.stage ===
    "awaiting_date"
) {
  const naturalDate =
    extractDate(
      msg
    );

  if (
    naturalDate
  ) {
    state.selectedDate =
      naturalDate;

    state.displayDate =
      naturalDate;

    state.dayName =
      dayName(
        naturalDate
      );

    state.selectedTime =
      "";

    state.availableSlots =
      [];

    state.availabilitySummaryRequested =
      false;

    state.stage =
      "awaiting_time";

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_slots";
  } else {
    /*
     * Example:
     *
     * What dates and times are available?
     */
    state.availabilitySummaryRequested =
      asksAvailability;

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_calendar";
  }
}

/*
 * ==================================================
 * 9. WAITING FOR TIME
 * ==================================================
 *
 * This is also the stage that Format Booking Result
 * MUST restore after a failed booking.
 *
 * Examples:
 *
 * First one
 * Go with the first one
 * Second one
 * Then go with the second one
 * Second time slot
 * 6 PM
 *
 * ==================================================
 */

else if (
  state.stage ===
    "awaiting_time"
) {
  const naturalTime =
    extractTime(
      msg,
      state.availableSlots
    );

  if (
    naturalTime
  ) {
    /*
     * Preserve the selected slot.
     */
    state.selectedTime =
      naturalTime;

    /*
     * Immediately attempt booking.
     *
     * We do not need an extra:
     *
     * "Can you confirm?"
     *
     * turn.
     */
    state.stage =
      "confirming";

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_confirm";
  } else {
    /*
     * Could not understand the requested time.
     *
     * Keep state intact and show times again.
     */
    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_slots";
  }
}

/*
 * ==================================================
 * 10. CONFIRMING
 * ==================================================
 *
 * Normally the database booking happens immediately
 * after entering this state.
 *
 * This fallback prevents random messages from
 * destroying the booking context if another request
 * arrives before result-state handling finishes.
 * ==================================================
 */

else if (
  state.stage ===
    "confirming"
) {
  /*
   * If user explicitly gives another time while
   * we're still marked confirming, allow recovery.
   */
  const alternativeTime =
    extractTime(
      msg,
      state.availableSlots
    );

  if (
    alternativeTime
  ) {
    state.selectedTime =
      alternativeTime;

    state.stage =
      "confirming";

    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_confirm";
  } else {
    /*
     * Keep context rather than falling to Gemini/general.
     */
    store.bookingStates[
      sessionId
    ] = state;

    route =
      "booking_confirm";
  }
}

/*
 * ==================================================
 * 11. NON-BOOKING ROUTES
 * ==================================================
 */

else if (
  /\b(doctor|doctors|specialist|cardiologist|neurologist|pediatric|gp|general practitioner)\b/.test(
    msg
  )
) {
  route =
    "doctors";
}

else if (
  asksInformationalFAQ
) {
  route =
    "faq";
}

else if (
  asksSymptoms
) {
  route =
    "symptom";
}

/*
 * ==================================================
 * OUTPUT
 * ==================================================
 */

const out = {
  ...item,

  /*
   * Original user text/STT transcript.
   */
  normalizedMessage:
    originalMessage,

  route,

  voiceMode,

  state,

  selectedDoctor:
    state.selectedDoctor ||
    selectedDoctor ||
    null,

  selectedDate:
    state.selectedDate ||
    item.selectedDate ||
    "",

  displayDate:
    state.displayDate ||
    item.displayDate ||
    "",

  dayName:
    state.dayName ||
    item.dayName ||
    "",

  selectedTime:
    state.selectedTime ||
    item.selectedTime ||
    "",

  operationState,

  appointmentId:
    operationState.appointmentId ||
    item.appointmentId ||
    "",

  newAppointmentDate:
    operationState.newAppointmentDate ||
    item.newAppointmentDate ||
    "",

  newAppointmentTime:
    operationState.newAppointmentTime ||
    item.newAppointmentTime ||
    "",

  cancellationReason:
    operationState.cancellationReason ||
    item.cancellationReason ||
    "",

  operationPrompt:
    item.operationPrompt ||
    "",
};

return [
  {
    json:
      out,
  },
];

const rows =
  $input
    .all()
    .map(
      (item) =>
        item.json
    );

const source =
  $(
    "Route + Booking State"
  )
    .first()
    .json;

const sessionId =
  source.sessionId ||
  "default";

const store =
  $getWorkflowStaticData(
    "global"
  );

if (
  !store.bookingStates
) {
  store.bookingStates =
    {};
}

const bookingMode =
  source.route ===
  "booking_doctors";

const doctors =
  rows.map(
    (row) => {
      let weeklySchedule =
        row.availableTimes ||
        {};

      if (
        typeof weeklySchedule ===
        "string"
      ) {
        try {
          weeklySchedule =
            JSON.parse(
              weeklySchedule
            );
        } catch {
          weeklySchedule =
            {};
        }
      }

      return {
        id:
          row.id,

        doctorId:
          row.id,

        doctorName:
          row.name,

        name:
          row.name,

        specialization:
          row.specialization ||
          "",

        designation:
          row.designation ||
          "",

        profileImageUrl:
          row.profileImageUrl ||
          "",

        yearsOfExperience:
          row.yearsOfExperience ||
          "",

        weeklySchedule,
      };
    }
  );

const previousState =
  store.bookingStates[
    sessionId
  ] || {
    stage:
      "idle",
  };

/*
 * IMPORTANT:
 *
 * Always store doctors in exactly the same
 * order that was shown to the user.
 *
 * This enables:
 *
 * "first doctor"
 * "second doctor"
 * etc.
 */
const newState = {
  ...previousState,

  currentDoctors:
    doctors,

  lastUpdated:
    new Date()
      .toISOString(),
};

if (
  bookingMode
) {
  newState.stage =
    "awaiting_doctor";

  newState.selectedDoctor =
    null;

  newState.selectedDate =
    "";

  newState.displayDate =
    "";

  newState.dayName =
    "";

  newState.selectedTime =
    "";

  newState.availableSlots =
    [];
}

store.bookingStates[
  sessionId
] = newState;

const doctorList =
  doctors
    .slice(
      0,
      6
    )
    .map(
      (
        doctor,
        index
      ) => {
        const name =
          String(
            doctor.name ||
              "Doctor"
          ).replace(
            /Dr\./gi,
            "Doctor"
          );

        return `${
          index + 1
        }. ${name} - ${
          doctor.specialization ||
          "General Practice"
        }`;
      }
    )
    .join(
      " "
    );

let reply;

if (
  doctors.length === 0
) {
  reply =
    "Sorry, no doctors are available right now.";
} else if (
  bookingMode
) {
  reply =
    `Please choose a doctor. ${doctorList}`;
} else {
  reply =
    `Our available doctors are: ${doctorList}`;
}

return [
  {
    json: {
      intent:
        bookingMode
          ? "booking_doctor_selection"
          : "doctor_list",

      reply,

      cards:
        doctors,

      doctors,

      bookingStep:
        bookingMode
          ? "none"
          : undefined,

      selectedDoctor:
        null,

      voiceMode:
        source.voiceMode,

      requestVoiceReply:
        source.requestVoiceReply,

      sessionId,

      email:
        source.email,
    },
  },
];

const src =
  $json;

const sessionId =
  src.sessionId ||
  "default";

const store =
  $getWorkflowStaticData(
    "global"
  );

if (
  !store.bookingStates
) {
  store.bookingStates =
    {};
}

const state =
  store.bookingStates[
    sessionId
  ] || {};

const doctor =
  state.selectedDoctor ||
  src.selectedDoctor ||
  {};

let weeklySchedule =
  doctor.weeklySchedule ||
  doctor.availableTimes ||
  {};

if (
  typeof weeklySchedule ===
  "string"
) {
  try {
    weeklySchedule =
      JSON.parse(
        weeklySchedule
      );
  } catch {
    weeklySchedule =
      {};
  }
}

const days = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
];

const calendar =
  [];

const today =
  new Date();

today.setHours(
  0,
  0,
  0,
  0
);

for (
  let offset = 0;
  offset < 30;
  offset++
) {
  const date =
    new Date(
      today
    );

  date.setDate(
    today.getDate() +
      offset
  );

  const dayKey =
    days[
      date.getDay()
    ];

  const dateString =
    `${date.getFullYear()}-${String(
      date.getMonth() + 1
    ).padStart(
      2,
      "0"
    )}-${String(
      date.getDate()
    ).padStart(
      2,
      "0"
    )}`;

  const slots =
    Array.isArray(
      weeklySchedule[
        dayKey
      ]
    )
      ? weeklySchedule[
          dayKey
        ]
      : [];

  calendar.push({
    date:
      dateString,

    displayDate:
      dateString,

    dayName:
      dayKey,

    available:
      slots.length >
      0,

    timeSlots:
      slots,
  });
}

state.stage =
  "awaiting_date";

const wantsSummary =
  state
    .availabilitySummaryRequested ===
  true;

state.availabilitySummaryRequested =
  false;

store.bookingStates[
  sessionId
] = state;

const doctorName =
  doctor.doctorName ||
  doctor.name ||
  "the doctor";

let reply =
  `Please choose an available date for ${doctorName}.`;

/*
 * Voice question:
 *
 * "What dates and times are available?"
 */
if (
  wantsSummary
) {
  const available =
    calendar
      .filter(
        (day) =>
          day.available
      )
      .slice(
        0,
        7
      );

  if (
    available.length >
    0
  ) {
    const summary =
      available
        .map(
          (day) => {
            return `${day.date}: ${day.timeSlots.join(
              ", "
            )}`;
          }
        )
        .join(
          "; "
        );

    reply =
      `${doctorName} has these upcoming available dates and times: ${summary}. Please choose a date.`;
  } else {
    reply =
      `I could not find any configured available dates for ${doctorName} in the next 30 days.`;
  }
}

return [
  {
    json: {
      intent:
        "calendar_selection",

      bookingStep:
        "date",

      reply,

      calendar,

      selectedDoctor:
        doctor,

      selectedDate:
        state.selectedDate ||
        "",

      voiceMode:
        src.voiceMode,

      requestVoiceReply:
        src.requestVoiceReply,

      sessionId,

      email:
        src.email,
    },
  },
];

const row =
  $json || {};

const src =
  $("Route + Booking State")
    .first()
    .json;

const sessionId =
  src.sessionId ||
  "default";

const store =
  $getWorkflowStaticData(
    "global"
  );

if (
  !store.bookingStates
) {
  store.bookingStates =
    {};
}

const state =
  store.bookingStates[
    sessionId
  ] || {};

const doctor =
  state.selectedDoctor ||
  src.selectedDoctor ||
  {};

const selectedDate =
  state.selectedDate ||
  src.selectedDate ||
  "";

const displayDate =
  state.displayDate ||
  src.displayDate ||
  selectedDate;

const doctorName =
  doctor.doctorName ||
  doctor.name ||
  row.name ||
  "the doctor";

let weeklySchedule =
  row.availableTimes ||
  doctor.weeklySchedule ||
  doctor.availableTimes ||
  {};

if (
  typeof weeklySchedule ===
  "string"
) {
  try {
    weeklySchedule =
      JSON.parse(
        weeklySchedule
      );
  } catch {
    weeklySchedule =
      {};
  }
}

let bookedTimes =
  row.bookedTimes ||
  [];

if (
  typeof bookedTimes ===
  "string"
) {
  try {
    bookedTimes =
      JSON.parse(
        bookedTimes
      );
  } catch {
    bookedTimes =
      [];
  }
}

if (
  !Array.isArray(
    bookedTimes
  )
) {
  bookedTimes =
    [];
}

function getDayName(
  dateString
) {
  if (!dateString) {
    return "";
  }

  const date =
    new Date(
      `${dateString}T12:00:00`
    );

  return [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday",
  ][date.getDay()];
}

function slotStartToDbTime(
  label
) {
  const start =
    String(
      label || ""
    )
      .split(" - ")[0]
      .trim();

  const match =
    start.match(
      /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/i
    );

  if (!match) {
    const dbMatch =
      start.match(
        /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/
      );

    if (!dbMatch) {
      return "";
    }

    return `${String(
      Number(
        dbMatch[1]
      )
    ).padStart(
      2,
      "0"
    )}:${dbMatch[2]}:${dbMatch[3] || "00"}`;
  }

  let hour =
    Number(
      match[1]
    );

  const minutes =
    match[2] ||
    "00";

  const meridiem =
    match[3]
      .toLowerCase();

  if (
    meridiem === "pm" &&
    hour !== 12
  ) {
    hour += 12;
  }

  if (
    meridiem === "am" &&
    hour === 12
  ) {
    hour = 0;
  }

  return `${String(
    hour
  ).padStart(
    2,
    "0"
  )}:${minutes}:00`;
}

const dayKey =
  getDayName(
    selectedDate
  );

const rawSlots =
  Array.isArray(
    weeklySchedule[
      dayKey
    ]
  )
    ? weeklySchedule[
        dayKey
      ]
    : [];

const bookedSet =
  new Set(
    bookedTimes.map(
      (value) =>
        String(
          value || ""
        )
          .slice(
            0,
            8
          )
    )
  );

const timeSlots =
  rawSlots.map(
    (label) => {
      const dbTime =
        slotStartToDbTime(
          label
        );

      return {
        label:
          String(
            label
          ),

        booked:
          dbTime
            ? bookedSet.has(
                dbTime
              )
            : false,
      };
    }
  );

state.availableSlots =
  timeSlots;

state.selectedTime =
  "";

const freeSlots =
  timeSlots.filter(
    (slot) =>
      !slot.booked
  );

if (
  rawSlots.length ===
  0
) {
  state.stage =
    "awaiting_date";

  state.selectedDate =
    "";

  state.displayDate =
    "";

  state.dayName =
    "";

  store.bookingStates[
    sessionId
  ] = state;

  return [
    {
      json: {
        intent:
          "booking_no_slots",

        success:
          false,

        reply:
          `${doctorName} has no configured appointment times on ${selectedDate}. Please choose another date.`,

        bookingStep:
          "date",

        timeSlots:
          [],

        selectedDoctor:
          doctor,

        selectedDate:
          "",

        voiceMode:
          src.voiceMode,

        requestVoiceReply:
          src.requestVoiceReply,

        sessionId,

        email:
          src.email,
      },
    },
  ];
}

if (
  freeSlots.length ===
  0
) {
  state.stage =
    "awaiting_date";

  state.selectedDate =
    "";

  state.displayDate =
    "";

  state.dayName =
    "";

  store.bookingStates[
    sessionId
  ] = state;

  return [
    {
      json: {
        intent:
          "booking_date_fully_booked",

        success:
          false,

        reply:
          `All configured appointment times for ${doctorName} on ${selectedDate} are already booked. Please choose another date.`,

        bookingStep:
          "date",

        timeSlots,

        selectedDoctor:
          doctor,

        selectedDate:
          "",

        voiceMode:
          src.voiceMode,

        requestVoiceReply:
          src.requestVoiceReply,

        sessionId,

        email:
          src.email,
      },
    },
  ];
}

state.stage =
  "awaiting_time";

store.bookingStates[
  sessionId
] = state;

const freeLabels =
  freeSlots.map(
    (slot) =>
      slot.label
  );

return [
  {
    json: {
      intent:
        "time_selection",

      success:
        true,

      bookingStep:
        "time",

      reply:
        `Available times for ${doctorName} on ${displayDate}: ${freeLabels.join(", ")}. Please choose a time.`,

      timeSlots,

      selectedDoctor:
        doctor,

      selectedDate,

      displayDate,

      dayName:
        dayKey,

      voiceMode:
        src.voiceMode,

      requestVoiceReply:
        src.requestVoiceReply,

      sessionId,

      email:
        src.email,
    },
  },
];

const booking =
  $json || {};

const src =
  $("Prepare Booking")
    .first()
    .json;

const store =
  $getWorkflowStaticData(
    "global"
  );

const sessionId =
  src.sessionId ||
  "default";

if (
  !store.bookingStates
) {
  store.bookingStates =
    {};
}

const state =
  store.bookingStates[
    sessionId
  ] || {};

let reply;
let intent;
let success =
  false;

/*
 * ==================================================
 * SUCCESS
 * ==================================================
 */

if (
  booking.id
) {
  success =
    true;

  intent =
    "booking_confirmed";

  reply =
    `Your appointment with ${
      src.doctorName ||
      "the doctor"
    } on ${
      src.displayDate ||
      src.selectedDate
    } at ${
      src.selectedTime
    } is confirmed. Appointment number ${
      booking.id
    }.`;

  /*
   * Booking finished successfully,
   * so clear the temporary booking state.
   */
  delete store
    .bookingStates[
      sessionId
    ];

  return [
    {
      json: {
        intent,

        success:
          true,

        bookingConfirmed:
          true,

        reply,

        appointment:
          booking,

        appointmentId:
          booking.id,

        selectedDoctor:
          state.selectedDoctor ||
          null,

        selectedDate:
          src.selectedDate ||
          state.selectedDate ||
          "",

        selectedTime:
          src.selectedTime ||
          state.selectedTime ||
          "",

        voiceMode:
          src.voiceMode,

        requestVoiceReply:
          src.voiceMode ===
            true ||
          src.requestVoiceReply ===
            true,

        sessionId,

        email:
          src.email,
      },
    },
  ];
}

/*
 * ==================================================
 * BOOKING FAILED
 * ==================================================
 *
 * IMPORTANT:
 *
 * Do NOT destroy:
 *
 * selectedDoctor
 * selectedDate
 * availableSlots
 *
 * The user should be able to say:
 *
 * "second one"
 *
 * immediately after a busy first slot.
 * ==================================================
 */

intent =
  "booking_failed";

success =
  false;

/*
 * Remove only the failed time choice.
 */
state.selectedTime =
  "";

/*
 * Return to time selection.
 */
state.stage =
  "awaiting_time";

/*
 * Keep doctor/date/availableSlots.
 */
store.bookingStates[
  sessionId
] = state;

const availableSlots =
  Array.isArray(
    state.availableSlots
  )
    ? state.availableSlots
    : [];

const slotLabels =
  availableSlots
    .filter(
      (slot) =>
        !(
          typeof slot === "object" &&
          slot?.booked === true
        )
    )
    .map(
      (slot) =>
        String(
          slot?.label ||
          slot ||
          ""
        )
    )
    .filter(
      Boolean
    );

reply =
  `That appointment time could not be booked. ` +
  `It may already be reserved. ` +
  (
    slotLabels.length >
    0
      ? `Please choose another available time: ${slotLabels.join(
          ", "
        )}.`
      : "Please choose another available time."
  );

return [
  {
    json: {
      intent,

      success:
        false,

      bookingConfirmed:
        false,

      bookingStep:
        "time",

      reply,

      timeSlots:
        availableSlots,

      selectedDoctor:
        state.selectedDoctor ||
        null,

      selectedDate:
        state.selectedDate ||
        src.selectedDate ||
        "",

      selectedTime:
        "",

      voiceMode:
        src.voiceMode,

      requestVoiceReply:
        src.voiceMode ===
          true ||
        src.requestVoiceReply ===
          true,

      sessionId,

      email:
        src.email,
    },
  },
];

const src =
  $json;

const question =
  String(
    src.normalizedMessage ||
    src.message ||
    src.transcript ||
    ""
  ).trim();

const originalRoute =
  String(
    src.route ||
    "general"
  ).trim();

if (!question) {
  return [
    {
      json: {
        question: "",
        originalRoute,
        intent:
          "rag_input_error",
        reply:
          "Please enter a question about the medical center.",
        nextRoute:
          "respond",
        voiceMode:
          src.voiceMode === true,
        requestVoiceReply:
          src.requestVoiceReply === true,
        sessionId:
          src.sessionId || "",
        email:
          src.email || "",
      },
    },
  ];
}

return [
  {
    json: {
      question,
      message:
        question,
      normalizedMessage:
        question,
      originalRoute,
      voiceMode:
        src.voiceMode === true,
      requestVoiceReply:
        src.requestVoiceReply === true,
      sessionId:
        src.sessionId || "",
      email:
        src.email || "",
    },
  },
];

const src =
  $json;

const followupPrompt =
  String(
    src.symptomFollowupPrompt ||
    ""
  ).trim();

/*
 * A yes/no follow-up from the symptom recommendation
 * state can come back through this same node without
 * running triage again.
 */
if (
  followupPrompt
) {
  return [
    {
      json: {
        intent:
          "symptom_booking_followup",

        reply:
          followupPrompt,

        needsDoctorLookup:
          false,

        urgency:
          "routine",

        recommendedSpecialty:
          "",

        voiceMode:
          src.voiceMode,

        requestVoiceReply:
          src.requestVoiceReply,

        sessionId:
          src.sessionId,

        email:
          src.email,
      },
    },
  ];
}

const message =
  String(
    src.normalizedMessage ||
    src.message ||
    src.transcript ||
    ""
  ).trim();

const m =
  message
    .toLowerCase()
    .replace(
      /[,.!?]/g,
      " "
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

/*
 * ==================================================
 * EMERGENCY RED FLAGS
 * ==================================================
 *
 * This is deliberately conservative. A routine doctor
 * booking must never be presented as a substitute for
 * emergency evaluation when a clear red flag is present.
 */
const emergencyRules = [
  {
    pattern:
      /\b(chest pain|chest pressure|chest tightness)\b.*\b(severe|crushing|sweating|faint|fainting|shortness of breath|difficulty breathing)\b|\b(severe|crushing)\b.*\b(chest pain|chest pressure|chest tightness)\b/,
    reason:
      "severe chest symptoms",
  },

  {
    pattern:
      /\b(can'?t breathe|cannot breathe|severe shortness of breath|severe difficulty breathing|struggling to breathe)\b/,
    reason:
      "severe breathing difficulty",
  },

  {
    pattern:
      /\b(face droop|facial droop|one[- ]sided weakness|weakness on one side|sudden numbness|slurred speech|cannot speak|can'?t speak|sudden confusion)\b/,
    reason:
      "possible stroke warning signs",
  },

  {
    pattern:
      /\b(worst headache|worst headache of my life|sudden severe headache|thunderclap headache)\b/,
    reason:
      "a sudden or unusually severe headache",
  },

  {
    pattern:
      /\bheadache\b.*\b(faint|fainting|confusion|one[- ]sided weakness|weakness on one side|vision loss|seizure|stiff neck)\b|\b(faint|fainting|confusion|one[- ]sided weakness|weakness on one side|vision loss|seizure|stiff neck)\b.*\bheadache\b/,
    reason:
      "headache with an urgent warning sign",
  },

  {
    pattern:
      /\b(severe bleeding|heavy bleeding|bleeding won'?t stop|uncontrolled bleeding)\b/,
    reason:
      "severe bleeding",
  },

  {
    pattern:
      /\b(unconscious|unresponsive|passed out and not waking|loss of consciousness)\b/,
    reason:
      "loss of consciousness",
  },

  {
    pattern:
      /\b(severe allergic reaction|anaphylaxis|swollen tongue|swelling of the tongue|throat swelling)\b/,
    reason:
      "a possible severe allergic reaction",
  },
];

const emergency =
  emergencyRules.find(
    (
      rule
    ) =>
      rule.pattern.test(
        m
      )
  );

if (
  emergency
) {
  return [
    {
      json: {
        intent:
          "symptom_emergency_guidance",

        urgency:
          "emergency",

        recommendedSpecialty:
          "",

        needsDoctorLookup:
          false,

        reply:
          `The symptoms you described include ${emergency.reason}, which can need urgent medical assessment. Please seek emergency medical care now or contact local emergency services. You may also contact the Medicare Medical Center emergency line at +94 11 234 5679. Do not wait for a routine appointment if symptoms are severe, sudden, or worsening.`,

        voiceMode:
          src.voiceMode,

        requestVoiceReply:
          src.requestVoiceReply,

        sessionId:
          src.sessionId,

        email:
          src.email,

        symptomMessage:
          message,
      },
    },
  ];
}

/*
 * ==================================================
 * SPECIALTY MAPPING
 * ==================================================
 *
 * This maps symptom categories to a suitable FIRST
 * clinical contact. It does not diagnose the patient.
 */
let recommendedSpecialty =
  "General Practitioner (GP)";

let symptomCategory =
  "general";

let urgency =
  "routine";

let guidancePrefix =
  "A General Practitioner is a suitable first point of contact for these symptoms.";

if (
  /\b(child|baby|infant|pediatric|paediatric)\b/.test(
    m
  )
) {
  recommendedSpecialty =
    "Pediatrics";

  symptomCategory =
    "pediatrics";

  guidancePrefix =
    "For a child-related concern, Pediatrics is a suitable first point of contact.";
} else if (
  /\b(palpitation|palpitations|heart racing|heart concern|heart problem)\b/.test(
    m
  )
) {
  recommendedSpecialty =
    "Cardiology";

  symptomCategory =
    "cardiology";

  guidancePrefix =
    "For a non-emergency heart-related concern, Cardiology may be an appropriate specialty.";
} else if (
  /\b(seizure|nerve pain|neurolog|recurrent migraine|recurrent headache|persistent headache|numbness|tingling)\b/.test(
    m
  )
) {
  recommendedSpecialty =
    "Neurology";

  symptomCategory =
    "neurology";

  guidancePrefix =
    "For persistent or recurrent neurological symptoms, Neurology may be an appropriate specialty.";
} else if (
  /\b(headache|fever|cough|sore throat|cold|flu|vomit|vomiting|nausea|diarrhea|stomach pain|abdominal pain|back pain|rash|fatigue|dizzy|dizziness|not feeling well|feel unwell|feeling unwell|general pain)\b/.test(
    m
  )
) {
  recommendedSpecialty =
    "General Practitioner (GP)";

  symptomCategory =
    "general";

  guidancePrefix =
    "A General Practitioner is a suitable first point of contact for these symptoms.";
}

/*
 * Severe symptoms without a specific emergency pattern
 * should still be assessed promptly.
 */
if (
  /\b(severe|very bad|getting worse|worsening|intense)\b/.test(
    m
  )
) {
  urgency =
    "urgent";

  guidancePrefix =
    `Because you described the symptoms as severe or worsening, you should be assessed by a clinician as soon as possible today. ${guidancePrefix}`;
}

return [
  {
    json: {
      intent:
        "symptom_triage",

      urgency,

      symptomCategory,

      recommendedSpecialty,

      guidancePrefix,

      needsDoctorLookup:
        true,

      symptomMessage:
        message,

      reply:
        "",

      voiceMode:
        src.voiceMode,

      requestVoiceReply:
        src.requestVoiceReply,

      sessionId:
        src.sessionId,

      email:
        src.email,
    },
  },
];

const r =
  $json;

const src =
  $(
    "Prepare General AI"
  )
    .first()
    .json;

const reply =
  r?.candidates?.[0]
    ?.content?.parts
    ?.map(
      (part) =>
        part.text || ""
    )
    .join(" ")
    .trim() ||
  "I do not have a verified answer for that question. Please contact reception for assistance.";

return [
  {
    json: {
      intent:
        src.ragFallback
          ? "general_fallback"
          : "general",
      reply,
      ragUsed:
        src.ragFallback === true,
      ragFallback:
        src.ragFallback === true,
      voiceMode:
        src.voiceMode,
      requestVoiceReply:
        src.requestVoiceReply,
      sessionId:
        src.sessionId,
      email:
        src.email,
    },
  },
];

const src =
  $json;

let reply =
  String(
    src.reply ||
    src.message ||
    ""
  ).trim();

if (!reply) {
  reply =
    "How can I help you?";
}

/*
 * Keep spoken replies reasonably concise.
 * Cards/calendar still remain available
 * in the JSON response.
 */
const ttsText =
  reply.length > 1500
    ? `${reply.slice(
        0,
        1500
      )}.`
    : reply;

return [
  {
    json: {
      ...src,

      reply,

      ttsText,

      voiceMode:
        true,
    },
  },
];

const source =
  $("Prepare TTS")
    .first()
    .json;

const ttsItem =
  $input.first();

const binaryKeys =
  Object.keys(
    ttsItem.binary ||
    {}
  );

if (
  binaryKeys.length === 0
) {
  throw new Error(
    "ElevenLabs TTS returned no audio file"
  );
}

const binaryKey =
  binaryKeys.includes(
    "data"
  )
    ? "data"
    : binaryKeys[0];

const buffer =
  await this.helpers.getBinaryDataBuffer(
    0,
    binaryKey
  );

if (
  buffer.length <
  500
) {
  throw new Error(
    "TTS returned an empty or invalid audio file"
  );
}

let transcript =
  source.transcript ||
  source.message ||
  "";

if (!transcript) {
  try {
    transcript =
      $("Normalize Voice")
        .first()
        .json
        .transcript ||
      "";
  } catch {
    transcript =
      "";
  }
}

return [
  {
    json: {
      reply:
        source.reply,

      transcript,

      intent:
        source.intent ||
        "general",

      cards:
        source.cards ||
        source.doctors ||
        null,

      doctors:
        source.doctors ||
        source.cards ||
        null,

      calendar:
        source.calendar ||
        null,

      bookingStep:
        source.bookingStep ||
        null,

      timeSlots:
        source.timeSlots ||
        null,

      bookingConfirmed:
        source.bookingConfirmed ||
        false,

      rescheduleMode:
        source.rescheduleMode ===
        true,

      selectedDate:
        source.selectedDate ||
        source.newAppointmentDate ||
        "",

      selectedTime:
        source.selectedTime ||
        source.newAppointmentTime ||
        "",

      appointmentOperation:
        source.appointmentOperation ||
        "none",

      appointmentId:
        source.appointmentId ||
        source.appointment?.id ||
        null,

      appointmentOperation:
        source.appointmentOperation ||
        "none",

      selectedDate:
        source.selectedDate ||
        source.appointment?.appointmentDate ||
        "",

      selectedTime:
        source.selectedTime ||
