function getDayName(
  dateString
) {
  if (!dateString) {
    return "";
  }

  const d =
    new Date(
      `${dateString}T12:00:00`
    );

  return [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday",
  ][d.getDay()];
}

function slotStartToDbTime(
  label
) {
  const start =
    String(
      label || ""
    )
      .split(" - ")[0]
      .trim();

  const match =
    start.match(
      /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/i
    );

  if (!match) {
    const dbMatch =
      start.match(
        /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/
      );

    if (!dbMatch) {
      return "";
    }

    return `${String(
      Number(
        dbMatch[1]
      )
    ).padStart(
      2,
      "0"
    )}:${dbMatch[2]}:${dbMatch[3] || "00"}`;
  }

  let hour =
    Number(
      match[1]
    );

  const minutes =
    match[2] ||
    "00";

  const meridiem =
    match[3]
      .toLowerCase();

  if (
    meridiem === "pm" &&
    hour !== 12
  ) {
    hour += 12;
  }

  if (
    meridiem === "am" &&
    hour === 12
  ) {
    hour = 0;
  }

  return `${String(
    hour
  ).padStart(
    2,
    "0"
  )}:${minutes}:00`;
}

const dayKey =
