    );

function specialtyMatches(
  doctorSpecialty,
  target
) {
  const d =
    String(
      doctorSpecialty ||
      ""
    )
      .toLowerCase();

  const t =
    String(
      target ||
      ""
    )
      .toLowerCase();

  if (
    t.includes(
      "general practitioner"
    ) ||
    t === "gp" ||
    t.includes(
      "general practice"
    )
  ) {
    return (
      d.includes(
        "general practitioner"
      ) ||
      d.includes(
        "general practice"
      ) ||
      /\bgp\b/.test(
        d
      )
    );
  }

  if (
    t.includes(
      "neurolog"
    )
  ) {
    return d.includes(
      "neurolog"
    );
  }

  if (
    t.includes(
      "cardiolog"
    )
  ) {
    return d.includes(
      "cardiolog"
    );
  }

  if (
    t.includes(
      "pediatric"
    ) ||
    t.includes(
      "paediatric"
    )
  ) {
    return (
      d.includes(
        "pediatric"
      ) ||
      d.includes(
        "paediatric"
      )
    );
  }

  return (
    d === t ||
    d.includes(
      t
    ) ||
    t.includes(
      d
    )
  );
}

