    selectedDoctor:
      null,

    symptomContext: {
      message:
        src.symptomMessage ||
        "",

      urgency:
        src.urgency ||
        "routine",

      recommendedSpecialty:
        requestedSpecialty,
    },
  };

  return [
    {
      json: {
        intent:
          "symptom_no_matching_doctor",

        urgency:
          src.urgency ||
          "routine",

        recommendedSpecialty:
          requestedSpecialty,

        reply:
          `${src.guidancePrefix || "A clinician should assess these symptoms."} I could not find a currently configured ${requestedSpecialty} doctor in the medical-center doctor list. Please contact reception for the most suitable available clinician. If symptoms become severe, sudden, or rapidly worsen, seek urgent in-person care.`,

        doctors:
          [],

        cards:
          [],

        bookingStep:
          "none",

        selectedDoctor:
          null,

        voiceMode:
          src.voiceMode,

        requestVoiceReply:
          src.requestVoiceReply,

        sessionId,

        email:
          src.email,
      },
    },
  ];
}

const state = {
  ...previousState,

  stage:
    "awaiting_symptom_booking_confirmation",

  currentDoctors:
    matchingDoctors,

  selectedDoctor:
    recommendedDoctor,

  selectedDate:
    "",

  displayDate:
    "",

  dayName:
    "",

  selectedTime:
    "",

  availableSlots:
    [],

  availabilitySummaryRequested:
    false,

  symptomContext: {
    message:
      src.symptomMessage ||
      "",

    urgency:
      src.urgency ||
      "routine",

    recommendedSpecialty:
      requestedSpecialty,

    resolvedSpecialty,
  },

  lastUpdated:
    new Date()
      .toISOString(),
};

store.bookingStates[
  sessionId
] = state;

const doctorName =
  recommendedDoctor.doctorName ||
  recommendedDoctor.name ||
  "the doctor";

const otherNames =
  matchingDoctors
    .slice(
      1,
      4
    )
    .map(
      (
        doctor
      ) =>
        doctor.doctorName ||
        doctor.name
    )
    .filter(
      Boolean
    );

let availabilitySentence =
  `At our medical center, ${doctorName} is listed under ${resolvedSpecialty}.`;

if (
  otherNames.length >
  0
) {
  availabilitySentence =
    `At our medical center, ${doctorName} is one available ${resolvedSpecialty} option. Other doctors listed for this specialty include ${otherNames.join(
      ", "
    )}.`;
}

const fallbackSentence =
  usedFallback
    ? ` We do not currently have a configured ${requestedSpecialty} doctor in the workflow, so a General Practitioner is being offered as the first clinical contact.`
    : "";

const urgentReminder =
  src.urgency ===
    "urgent"
    ? " If the symptoms become sudden, much worse, or include emergency warning signs such as fainting, confusion, one-sided weakness, severe breathing difficulty, or a sudden worst-ever headache, seek emergency care instead of waiting for a routine appointment."
    : "";

const reply =
  `${src.guidancePrefix || "A clinician should assess these symptoms."}${fallbackSentence} ${availabilitySentence}${urgentReminder} Would you like to book an appointment with ${doctorName}?`;

return [
  {
    json: {
      intent:
        "symptom_doctor_recommendation",

      urgency:
        src.urgency ||
        "routine",

      recommendedSpecialty:
        resolvedSpecialty,

      requestedSpecialty,

      reply,

      bookingPrompt:
        true,

      bookingStep:
        "none",

      selectedDoctor:
        recommendedDoctor,

      recommendedDoctor,

      doctors:
        matchingDoctors,

      cards:
        matchingDoctors,

      voiceMode:
        src.voiceMode,

      requestVoiceReply:
        src.requestVoiceReply,

      sessionId,

      email:
        src.email,
    },
  },
];

const response =
  $json || {};

const src =
  $(
    "Prepare RAG Query"
  )
    .first()
    .json;

const question =
  String(
    src.question ||
    ""
  ).trim();

const answer =
  String(
    response.answer ||
    ""
  ).trim();

const reason =
  String(
    response.reason ||
    ""
  ).trim();

const confidence =
  String(
    response.confidence ||
    ""
  ).trim();

const matchedTitle =
  String(
    response.matched_title ||
    ""
  ).trim();

const score =
  Number.isFinite(
    Number(
      response.score
    )
  )
    ? Number(
        response.score
      )
    : null;

const protectedReasons =
  new Set([
    "emergency_case",
    "medical_advice_request",
    "user_requested_human",
  ]);

const lowConfidenceReasons =
  new Set([
    "no_match_found",
    "low_confidence_match",
  ]);

/*
 * Safety/handover outcomes from the RAG API are never
 * sent to Gemini. Use the safe RAG response directly.
 */
if (
  protectedReasons.has(
    reason
  ) &&
  answer
) {
  return [
    {
      json: {
        nextRoute:
          "respond",
        intent:
          reason ===
          "emergency_case"
            ? "rag_safety_emergency"
            : reason ===
              "medical_advice_request"
              ? "rag_safety_medical_advice"
              : "rag_human_request",
        reply:
          answer,
        ragUsed:
          true,
        ragFallback:
          false,
        ragReason:
          reason,
        ragConfidence:
          confidence ||
          "high",
        ragMatchedTitle:
          matchedTitle ||
          null,
        ragScore:
          score,
        voiceMode:
          src.voiceMode,
        requestVoiceReply:
          src.requestVoiceReply,
        sessionId:
          src.sessionId,
        email:
          src.email,
      },
    },
  ];
}

/*
 * A confident knowledge-base answer is returned directly.
 * This prevents Gemini from rewriting verified clinic facts.
 */
if (
  response.handover_needed !==
    true &&
  answer &&
  (
    confidence ===
      "high" ||
    confidence ===
      "medium" ||
    (
      score !== null &&
      score >= 0.45
    )
  )
) {
  return [
    {
      json: {
        nextRoute:
          "respond",
        intent:
          src.originalRoute ===
          "faq"
            ? "rag_faq"
            : "rag_general",
        reply:
          answer,
        ragUsed:
          true,
        ragFallback:
          false,
        ragReason:
          null,
        ragConfidence:
          confidence ||
          "medium",
        ragMatchedTitle:
          matchedTitle ||
          null,
        ragScore:
          score,
        voiceMode:
          src.voiceMode,
        requestVoiceReply:
          src.requestVoiceReply,
        sessionId:
          src.sessionId,
        email:
          src.email,
      },
    },
  ];
}

/*
 * Low-confidence/no-match/temporary failures fall back to
 * the restricted Gemini receptionist. Gemini is told not
 * to invent medical-center facts.
 */
const fallbackReason =
  lowConfidenceReasons.has(
    reason
  )
    ? reason
    : (
        response.detail ||
        response.error ||
        reason ||
        "rag_unavailable_or_unverified"
      );

return [
  {
    json: {
      nextRoute:
        "fallback_ai",
      intent:
        "rag_fallback",
      question,
      message:
        question,
      normalizedMessage:
        question,
      originalRoute:
        src.originalRoute ||
        "general",
      ragUsed:
        true,
      ragFallback:
        true,
      ragReason:
        String(
          fallbackReason
        ),
      ragConfidence:
        confidence ||
        "low",
      ragMatchedTitle:
        matchedTitle ||
        null,
      ragScore:
        score,
      voiceMode:
        src.voiceMode,
      requestVoiceReply:
        src.requestVoiceReply,
      sessionId:
        src.sessionId,
      email:
        src.email,
    },
  },
];
